import { CLI_ENV } from './env.util';
const { Console } = require('console');
const { Transform } = require('stream');

class Logger {
  log = (...args: Parameters<typeof console.log>) => {
    console.log(...args);
  };
  logJson = (obj?: any, log = console.log) => {
    log(stringify(obj));
  };
  table = table;

  dev = (() => {
    // prevent infinite .dev autocomplete: logger.dev.dev.dev.dev
    const { dev, ...rest } = this;
    return new Proxy(rest, {
      get(target, prop) {
        return CLI_ENV === 'development'
          ? // @ts-ignore
            target[prop]
          : () => {};
      },
    });
  })();
}

const logger = new Logger();

const COLOR_MAP = {
  black: 30,
  red: 31,
  green: 32,
  yellow: 33,
  blue: 34,
  magenta: 35,
  cyan: 36,
  white: 37,
};

type Color = keyof typeof COLOR_MAP;

export const withColor = (text: string, color: Color = 'yellow') =>
  `\x1b[${COLOR_MAP[color]}m${text}\x1b[0m`;

export default logger;

function stringify(obj: any) {
  let cache: any = [];
  let str = JSON.stringify(
    obj,
    function (key, value) {
      if (typeof value === 'object' && value !== null) {
        if (cache.indexOf(value) !== -1) {
          // Circular reference found, discard key
          return;
        }
        // Store value in our collection
        cache.push(value);
      }
      return value;
    },
    2,
  );
  cache = null; // reset the cache
  return str;
}

function table(data: any) {
  // @see https://stackoverflow.com/a/67859384
  const ts = new Transform({
    transform(chunk: any, enc: any, cb: any) {
      cb(null, chunk);
    },
  });
  const logger = new Console({ stdout: ts });
  logger.table(data);
  const table = (ts.read() || '').toString();
  let result = '';
  for (let row of table.split(/[\r\n]+/)) {
    let r = row.replace(/[^┬]*┬/, '┌');
    r = r.replace(/^├─*┼/, '├');
    r = r.replace(/│[^│]*/, '');
    r = r.replace(/^└─*┴/, '└');
    r = r.replace(/'/g, ' ');
    result += `${r}\n`;
  }
  console.log(result);
}
